// Usage: bun perf.ts <repo root> [items]
// Seeds a scratch library with article-sized metadata and times the main-process read paths.
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { pathToFileURL } from "node:url";

const root = resolve(process.argv[2] ?? ".");
const items = Number(process.argv[3] ?? 2000);
const dir = mkdtempSync(join(tmpdir(), "squ15-perf-"));
const { openTestLibrary } = await import(
  pathToFileURL(join(root, "electron/storage/test-library.ts")).href
);
const { TEXT_MODEL } = await import(pathToFileURL(join(root, "electron/embedding-contract.ts")).href);

const dimension = 768;
const rand = (() => {
  let state = 42;
  return () => (state = (state * 1664525 + 1013904223) % 4294967296) / 4294967296;
})();
const paragraph = "Local first software keeps the library on the user's disk and stays quiet. ".repeat(
  6,
);
const html = `<article>${`<p>${paragraph}</p>`.repeat(90)}</article>`; // ~40 kB
const vector = (seedShift: number) => {
  const values = Float32Array.from({ length: dimension }, () => rand() - 0.5 + seedShift);
  const norm = Math.hypot(...values);
  return Buffer.from(values.map((value) => value / norm).buffer);
};

const library = await openTestLibrary(join(dir, "library.sqlite3"));
try {
  const insert = library.db.prepare(`INSERT INTO items
    (id, kind, title, description, body, source_label, ocr_text, metadata, created_at, updated_at)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`);
  library.db.exec("BEGIN");
  for (let index = 0; index < items; index += 1) {
    const kind = index % 4 === 0 ? "note" : "article";
    const metadata = JSON.stringify({
      html: kind === "article" ? html : "",
      text: kind === "article" ? html.replace(/<[^>]+>/g, "") : "",
      tags: ["alpha", "beta"],
      imageUrls: ["https://example.invalid/a.jpg"],
      mediaWidth: 800,
      mediaHeight: 600,
    });
    insert.run(
      `perf-${index}`,
      kind,
      `Item ${index} lanterns`,
      "Short description",
      "",
      "example.invalid",
      index % 3 === 0 ? "scanned text ".repeat(400) : "",
      metadata,
      index,
      index,
    );
  }
  library.db.exec("COMMIT");
  for (let index = 0; index < items; index += 1) {
    await library.storeEmbedding(`perf-${index}`, "text", TEXT_MODEL, vector(0.01), dimension);
  }
  const queryVector = Float32Array.from({ length: dimension }, () => rand() - 0.5 + 0.01);

  const time = async (label: string, run: () => Promise<unknown>) => {
    await run();
    const samples: number[] = [];
    for (let index = 0; index < 5; index += 1) {
      const started = performance.now();
      await run();
      samples.push(performance.now() - started);
    }
    samples.sort((a, b) => a - b);
    console.log(`${label.padEnd(26)} median ${samples[2].toFixed(1)} ms  (min ${samples[0].toFixed(1)}, max ${samples[4].toFixed(1)})`);
  };
  console.log(`${items} items, ~${Math.round(html.length / 1024)} kB html each, root ${root}`);
  await time("listActiveItems", () => library.listActiveItems());
  await time("searchItems lexical", () => library.searchItems("lanterns"));
  await time("searchItems hybrid", () => library.searchItems("lanterns", 100, queryVector));
  await time("searchSimilar", () => library.searchSimilar("perf-1", "text"));
} finally {
  await library.close();
  rmSync(dir, { recursive: true, force: true });
}

